func Handler(si ServerInterface) http.Handler {
	return HandlerWithOptions(si, ChiServerOptions{})
}

type ChiServerOptions struct {
	BaseURL          string
	BaseRouter       chi.Router
	Middlewares      []MiddlewareFunc
	ErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

// HandlerFromMux creates http.Handler with routing matching OpenAPI spec based on the provided mux.
func HandlerFromMux(si ServerInterface, r chi.Router) http.Handler {
	return HandlerWithOptions(si, ChiServerOptions{
		BaseRouter: r,
	})
}

func HandlerFromMuxWithBaseURL(si ServerInterface, r chi.Router, baseURL string) http.Handler {
	return HandlerWithOptions(si, ChiServerOptions{
		BaseURL:    baseURL,
		BaseRouter: r,
	})
}

// HandlerWithOptions creates http.Handler with additional options
func HandlerWithOptions(si ServerInterface, options ChiServerOptions) http.Handler {
	r := options.BaseRouter

	if r == nil {
		r = chi.NewRouter()
	}
	if options.ErrorHandlerFunc == nil {
		options.ErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}
	wrapper := ServerInterfaceWrapper{
		Handler:            si,
		HandlerMiddlewares: options.Middlewares,
		ErrorHandlerFunc:   options.ErrorHandlerFunc,
	}

	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/v1/practices/{practiceId}/slots", wrapper.ListOpenSlots)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/v1/practices/{practiceId}/holds", wrapper.HoldSlot)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/v1/me/appointments", wrapper.ListMyAppointments)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/v1/me/appointments/{appointmentId}", wrapper.GetMyAppointment)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/v1/me/appointments/{appointmentId}/checkout", wrapper.CheckoutAppointment)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/v1/me/appointments/{appointmentId}/cancel-preview", wrapper.PreviewCancelAppointment)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/v1/me/appointments/{appointmentId}/cancel", wrapper.CancelAppointment)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/v1/me/appointments/{appointmentId}/reschedule", wrapper.RescheduleAppointment)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/v1/practices/{practiceId}/availability", wrapper.GetAvailability)
	})
	r.Group(func(r chi.Router) {
		r.Put(options.BaseURL+"/v1/practices/{practiceId}/availability", wrapper.SetAvailability)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/v1/practices/{practiceId}/availability/exceptions", wrapper.AddAvailabilityException)
	})
	r.Group(func(r chi.Router) {
		r.Delete(options.BaseURL+"/v1/practices/{practiceId}/availability/exceptions/{exceptionId}", wrapper.RemoveAvailabilityException)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/v1/practices/{practiceId}/availability/conflicts", wrapper.ListAvailabilityConflicts)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/v1/practices/{practiceId}/day", wrapper.GetPracticeDay)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/v1/appointments/{appointmentId}/marks", wrapper.MarkAppointment)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/v1/appointments/{appointmentId}/staff-cancel", wrapper.StaffCancelAppointment)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/v1/appointments/{appointmentId}/reconfirm", wrapper.ReconfirmAppointment)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/v1/clinics/{clinicId}/reconfirmations", wrapper.ListReconfirmations)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/v1/clinics/{clinicId}/closures", wrapper.ListClinicClosures)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/v1/clinics/{clinicId}/closures", wrapper.CloseClinic)
	})

	return r
}

