// StrictServerInterface represents all server handlers.
type StrictServerInterface interface {
	// MarkAppointment Mark arrived, completed, patient no-show or doctor no-show (audited)
	// (POST /v1/appointments/{appointmentId}/marks)
	MarkAppointment(ctx context.Context, request MarkAppointmentRequestObject) (MarkAppointmentResponseObject, error)
	// ReconfirmAppointment The clinic confirms the doctor will be there (day-before task)
	// (POST /v1/appointments/{appointmentId}/reconfirm)
	ReconfirmAppointment(ctx context.Context, request ReconfirmAppointmentRequestObject) (ReconfirmAppointmentResponseObject, error)
	// StaffCancelAppointment Cancel on behalf of the doctor or the clinic (full refund, RF04)
	// (POST /v1/appointments/{appointmentId}/staff-cancel)
	StaffCancelAppointment(ctx context.Context, request StaffCancelAppointmentRequestObject) (StaffCancelAppointmentResponseObject, error)
	// ListClinicClosures Closures of my clinic (counts only, no patient data)
	// (GET /v1/clinics/{clinicId}/closures)
	ListClinicClosures(ctx context.Context, request ListClinicClosuresRequestObject) (ListClinicClosuresResponseObject, error)
	// CloseClinic Close my clinic (or one branch) for a local date; cancel or ask patients to reschedule
	// (POST /v1/clinics/{clinicId}/closures)
	CloseClinic(ctx context.Context, request CloseClinicRequestObject) (CloseClinicResponseObject, error)
	// ListReconfirmations Appointments the clinic has not yet reconfirmed (no patient identity)
	// (GET /v1/clinics/{clinicId}/reconfirmations)
	ListReconfirmations(ctx context.Context, request ListReconfirmationsRequestObject) (ListReconfirmationsResponseObject, error)
	// ListMyAppointments My appointments, newest first
	// (GET /v1/me/appointments)
	ListMyAppointments(ctx context.Context, request ListMyAppointmentsRequestObject) (ListMyAppointmentsResponseObject, error)
	// GetMyAppointment One of my appointments
	// (GET /v1/me/appointments/{appointmentId})
	GetMyAppointment(ctx context.Context, request GetMyAppointmentRequestObject) (GetMyAppointmentResponseObject, error)
	// CancelAppointment Cancel my appointment, acknowledging the refund outcome that was shown
	// (POST /v1/me/appointments/{appointmentId}/cancel)
	CancelAppointment(ctx context.Context, request CancelAppointmentRequestObject) (CancelAppointmentResponseObject, error)
	// PreviewCancelAppointment What a cancellation would refund, shown before the patient confirms
	// (GET /v1/me/appointments/{appointmentId}/cancel-preview)
	PreviewCancelAppointment(ctx context.Context, request PreviewCancelAppointmentRequestObject) (PreviewCancelAppointmentResponseObject, error)
	// CheckoutAppointment Open the hosted checkout for a held appointment (the amount is the fee copied at hold time)
	// (POST /v1/me/appointments/{appointmentId}/checkout)
	CheckoutAppointment(ctx context.Context, request CheckoutAppointmentRequestObject) (CheckoutAppointmentResponseObject, error)
	// RescheduleAppointment Move my confirmed appointment to another open slot of the same practice and mode (no refund, payment stays)
	// (POST /v1/me/appointments/{appointmentId}/reschedule)
	RescheduleAppointment(ctx context.Context, request RescheduleAppointmentRequestObject) (RescheduleAppointmentResponseObject, error)
	// GetAvailability Weekly template and exceptions of my practice
	// (GET /v1/practices/{practiceId}/availability)
	GetAvailability(ctx context.Context, request GetAvailabilityRequestObject) (GetAvailabilityResponseObject, error)
	// SetAvailability Replace the weekly template. Booked slots are never deleted; conflicts are returned
	// (PUT /v1/practices/{practiceId}/availability)
	SetAvailability(ctx context.Context, request SetAvailabilityRequestObject) (SetAvailabilityResponseObject, error)
	// ListAvailabilityConflicts Booked appointments that no longer fit the availability (to reschedule)
	// (GET /v1/practices/{practiceId}/availability/conflicts)
	ListAvailabilityConflicts(ctx context.Context, request ListAvailabilityConflictsRequestObject) (ListAvailabilityConflictsResponseObject, error)
	// AddAvailabilityException Add a leave or closure (local dates in the practice zone)
	// (POST /v1/practices/{practiceId}/availability/exceptions)
	AddAvailabilityException(ctx context.Context, request AddAvailabilityExceptionRequestObject) (AddAvailabilityExceptionResponseObject, error)
	// RemoveAvailabilityException Remove a leave or closure
	// (DELETE /v1/practices/{practiceId}/availability/exceptions/{exceptionId})
	RemoveAvailabilityException(ctx context.Context, request RemoveAvailabilityExceptionRequestObject) (RemoveAvailabilityExceptionResponseObject, error)
	// GetPracticeDay Day view of appointments (booking fields only), by local date in the practice zone
	// (GET /v1/practices/{practiceId}/day)
	GetPracticeDay(ctx context.Context, request GetPracticeDayRequestObject) (GetPracticeDayResponseObject, error)
	// HoldSlot Hold a slot for 15 minutes (creates the appointment in state held)
	// (POST /v1/practices/{practiceId}/holds)
	HoldSlot(ctx context.Context, request HoldSlotRequestObject) (HoldSlotResponseObject, error)
	// ListOpenSlots Open slots of a listed practice, earliest first
	// (GET /v1/practices/{practiceId}/slots)
	ListOpenSlots(ctx context.Context, request ListOpenSlotsRequestObject) (ListOpenSlotsResponseObject, error)
}

type StrictHandlerFunc func(ctx context.Context, w http.ResponseWriter, r *http.Request, request any) (any, error)
type StrictMiddlewareFunc func(f StrictHandlerFunc, operationID string) StrictHandlerFunc

type StrictHTTPServerOptions struct {
	RequestErrorHandlerFunc  func(w http.ResponseWriter, r *http.Request, err error)
	ResponseErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

func NewStrictHandler(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc) ServerInterface {
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: StrictHTTPServerOptions{
		RequestErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		},
		ResponseErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		},
	}}
}

func NewStrictHandlerWithOptions(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc, options StrictHTTPServerOptions) ServerInterface {
	if options.RequestErrorHandlerFunc == nil {
		options.RequestErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}
	if options.ResponseErrorHandlerFunc == nil {
		options.ResponseErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		}
	}
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: options}
}

type strictHandler struct {
	ssi         StrictServerInterface
	middlewares []StrictMiddlewareFunc
	options     StrictHTTPServerOptions
}

